#include <limits>
#include <iostream>

int main() {
    // Type-safe retrieval of maximum value for long long
    long long max_ll = std::numeric_limits<long long>::max();

    // Floating point properties
    double epsilon = std::numeric_limits<double>::epsilon();

    // Integer properties
    bool is_signed = std::numeric_limits<int>::is_signed;

    std::cout << "Max long long: " << max_ll << std::endl;
    std::cout << "Double Epsilon: " << epsilon << std::endl;
    std::cout << "Is int signed: " << std::boolalpha << is_signed << std::endl;
}
